from importlib.machinery import SourceFileLoader
w=SourceFileLoader('w','.literalgen-state/de-en-ru/1sa-root-native-write.py').load_module()
r=[
('Und Saul redete zu Jonathan, seinem Sohn, und zu allen seinen Knechten, David zu töten; Jonathan aber, Sauls Sohn, hatte großes Gefallen an David.','Nah am Hebräischen.'),
('Und Jonathan berichtete David und sagte: „Mein Vater Saul sucht dich zu töten; und nun hüte dich doch am Morgen und bleib im Versteck und verbirg dich.','Jonathan und David werden ausdrücklich genannt; die Bitte enthält eine Bittepartikel.'),
('Und ich werde hinausgehen und neben meinem Vater auf dem Feld stehen, wo du bist; und ich werde über dich zu meinem Vater reden und sehen, was ist, und es dir berichten.“','Nah am Hebräischen.'),
('Und Jonathan redete Gutes über David zu Saul, seinem Vater, und sagte zu ihm: „Der König sündige nicht gegen seinen Knecht, gegen David, denn er hat nicht gegen dich gesündigt, und seine Taten sind sehr gut für dich.','Das Gute wird ohne ausdrücklichen Superlativ genannt.'),
('Und er legte seine Seele in seine Handfläche und schlug den Philister; und der HERR wirkte eine große Rettung für ganz Israel. Du hast es gesehen und dich gefreut; und warum willst du an unschuldigem Blut sündigen, David ohne Grund zu töten?“','Die Seele wird ausdrücklich in seine Handfläche gelegt.'),
('Und Saul hörte auf die Stimme Jonathans, und Saul schwor: „So wahr der HERR lebt, er soll nicht getötet werden!“','Saul wird beim Schwören wiederholt genannt; das Getötetwerden steht passiv, nicht nur das Sterben.'),
('Und Jonathan rief David, und Jonathan berichtete ihm alle diese Worte, und Jonathan brachte David zu Saul; und er war vor ihm wie gestern und vorgestern.','Jonathan wird dreimal genannt; die Zeitangabe lautet wörtlich „wie gestern und vorgestern“.'),
('Und der Krieg brach wieder aus; und David zog aus und kämpfte gegen die Philister und schlug sie mit einem großen Schlag, und sie flohen vor ihm.','Schlagen und Schlag wiederholen denselben Wortstamm.'),
('Und ein böser Geist des HERRN war über Saul, und er saß in seinem Haus, und sein Speer war in seiner Hand, und David spielte mit der Hand.','Ein Instrument wird hier nicht eigens genannt; das Spielen geschieht mit der Hand.'),
('Und Saul suchte David mit dem Speer gegen die Wand zu schlagen; und er entkam vor Saul, und Saul schlug den Speer in die Wand. David aber floh und entrann in jener Nacht.','Das Schlagen des Speers in die Wand hat einen handelnden Mann zum Subjekt, nicht den Speer selbst.'),
('Und Saul sandte Boten zum Haus Davids, um ihn zu bewachen und ihn am Morgen zu töten. Und Michal, seine Frau, berichtete David und sagte: „Wenn du deine Seele nicht in dieser Nacht rettest, wirst du morgen getötet.“','Das Getötetwerden ist passiv ausgedrückt; die Seele wird ausdrücklich genannt.'),
('Und Michal ließ David durch das Fenster hinab; und er ging und floh und entrann.','David wird ausdrücklich genannt; Gehen, Fliehen und Entrinnen sind getrennte Verben.'),
('Und Michal nahm die Teraphim und legte sie ins Bett; und ein Geflecht aus Ziegenhaar legte sie zu seinen Häupten und bedeckte es mit dem Kleid.','Teraphim ist eine Mehrzahlform; beim Kleid steht die Einzahl. Die Kopfbedeckung wird als Geflecht aus Ziegenhaar wiedergegeben.'),
('Und Saul sandte Boten, David zu holen; und sie sagte: „Er ist krank.“','Nah am Hebräischen.'),
('Und Saul sandte die Boten, David zu sehen, und sagte: „Bringt ihn im Bett zu mir herauf, um ihn zu töten!“','Die Zweckangabe nennt das Töten aktiv, nicht ein passives Getötetwerden.'),
('Und die Boten kamen, und siehe, die Teraphim waren im Bett und das Geflecht aus Ziegenhaar zu seinen Häupten.','Teraphim ist eine Mehrzahlform; das Geflecht aus Ziegenhaar steht an der Kopfstelle.'),
('Und Saul sagte zu Michal: „Warum hast du mich so getäuscht und meinen Feind fortgeschickt, und er ist entronnen?“ Und Michal sagte zu Saul: „Er sagte zu mir: ‚Schick mich fort! Warum sollte ich dich töten?‘“','Die Drohung ist als Frage „Warum sollte ich dich töten?“ formuliert, nicht als „oder ich töte dich“.'),
('Und David floh und entrann und kam zu Samuel nach Rama und berichtete ihm alles, was Saul ihm getan hatte; und er und Samuel gingen und wohnten in Najoth.','Nah am Hebräischen.'),
('Und Saul wurde berichtet: „Siehe, David ist in Najoth in Rama.“','Nah am Hebräischen.'),
('Und Saul sandte Boten, David zu holen; und man sah die Schar der Propheten weissagen, und Samuel stand als Aufgestellter über ihnen. Und der Geist Gottes war auf den Boten Sauls, und auch sie weissagten.','Das Sehen steht im Hebräischen in der Einzahl; Samuel wird als stehend beschrieben.'),
('Und sie berichteten Saul, und er sandte andere Boten, und auch sie weissagten; und Saul sandte noch ein drittes Mal Boten, und auch sie weissagten.','Das Berichten an Saul wird aktiv mit ungenannten Handelnden erzählt.'),
('Und auch er ging nach Rama und kam bis zur großen Zisterne in Seku und fragte und sagte: „Wo sind Samuel und David?“ Und einer sagte: „Siehe, in Najoth in Rama.“','Der Antwortende bleibt ungenannt; das Antworten ist aktiv in der Einzahl erzählt.'),
('Und er ging dorthin nach Najoth in Rama; und auch auf ihm war der Geist Gottes, und er ging immerfort und weissagte, bis er nach Najoth in Rama kam.','Nah am Hebräischen.'),
('Und auch er zog seine Kleider aus, und auch er weissagte vor Samuel und fiel nackt nieder den ganzen Tag und die ganze Nacht. Darum sagt man: „Ist auch Saul unter den Propheten?“','Nah am Hebräischen.')]
